const input = $input.first()?.json ?? {};
const body = input.body ?? input;

return [{
  json: {
    config: {
      companyName: body.companyName || 'ABM Solutions Demo',
      senderName: body.senderName || 'Demo Sender',
      senderEmail: body.senderEmail || 'demo@example.com',
      slackWebhookUrl: body.slackWebhookUrl || 'REPLACE_WITH_SLACK_WEBHOOK_URL',
      hubspotToken: body.hubspotToken || 'REPLACE_WITH_HUBSPOT_PRIVATE_APP_TOKEN',
      openAiApiKey: body.openAiApiKey || 'REPLACE_WITH_OPENAI_API_KEY',
      demoMode: body.demoMode !== false
    },
    payload: body
  }
}];

const d=$input.first().json,s=d.source,t=d.target;
const fields=['email','firstName','lastName','company','status'];
const changes={};
for(const f of fields) if(String(s[f]??'')!==String(t?.[f]??'')) changes[f]=s[f];
let action='noop';
if(!t?.id) action='create';
else if(Object.keys(changes).length&&new Date(s.updatedAt)>=new Date(t.updatedAt)) action='update';
else if(Object.keys(changes).length) action='review_conflict';
return [{json:{...d,result:{action,recordKey:s.email,changes,sourceUpdatedAt:s.updatedAt,targetUpdatedAt:t?.updatedAt||null,syncTimestamp:new Date().toISOString()}}}];
